raw_commands:
{%- set R = "POS Receipt" -%}
{%- set W = 32 -%}
{%- set sgn = -1 if doc.is_return else 1 -%}
{%- if print_settings is defined and print_settings -%}
{%- set uom_after_qty = print_settings.print_uom_after_quantity -%}
{%- else -%}
{%- set uom_after_qty = frappe.db.get_single_value("Print Settings", "print_uom_after_quantity") -%}
{%- endif -%}
{%- macro money(v) -%}{{ frappe.utils.fmt_money(v) }}{%- endmacro -%}
{%- macro qty(v) -%}{%- if v == (v | int) -%}{{ frappe.utils.fmt_money(v, precision=0) }}{%- else -%}{{ frappe.utils.fmt_money(v, precision=3).rstrip("0") }}{%- endif -%}{%- endmacro -%}
{#- label left, value right on one line of W columns; the value drops to its own line when both do not fit -#}
{%- macro row(label, value="") -%}
{%- set label = label | string -%}{%- set value = value | string -%}
{%- if label | length + value | length + 1 <= W -%}{{ label ~ " " * (W - label | length - value | length) ~ value }}
{%- else -%}{{ label }}{% if value %}
{{ " " * (W - value | length) ~ value }}{% endif %}{%- endif -%}
{%- endmacro -%}
{%- if doc.select_print_heading -%}{%- set title = _(doc.select_print_heading, context=R) -%}
{%- elif doc.is_return -%}{%- set title = _("Credit Note", context=R) -%}
{%- else -%}{%- set title = _("Invoice", context=R) -%}{%- endif -%}
{%- if doc.rounded_total and not doc.disable_rounded_total -%}{%- set total_due = doc.rounded_total -%}{%- else -%}{%- set total_due = doc.grand_total -%}{%- endif -%}
{%- set company = frappe.db.get_value("Company", doc.company, ["phone_no", "tax_id"], as_dict=True) or {} -%}
{%- set cashier = frappe.db.get_value("User", doc.owner, "full_name") or doc.owner -%}
{%- set rule = "-" * W -%}
{{ "\x1B@" }}{{ "\x1Ba\x01" }}{{ "\x1B!\x08" }}{{ doc.company }}{{ "\x1B!\x00" }}
{% if company.phone_no %}{{ _("Tel.", context=R) }} {{ company.phone_no }}
{% endif %}{% if company.tax_id %}{{ _("Tax ID", context=R) }} {{ company.tax_id }}
{% endif %}{{ "\x1B!\x08" }}{{ title | upper }}{{ "\x1B!\x00" }}
{% if doc.docstatus == 0 %}*** {{ _("Draft", context=R) | upper }} ***
{% elif doc.docstatus == 2 %}*** {{ _("Cancelled", context=R) | upper }} ***
{% endif %}{{ "\x1Ba\x00" }}{{ row(_("No.", context=R), doc.name) }}
{{ row(_("Date", context=R), frappe.utils.format_date(doc.posting_date) ~ " " ~ (frappe.utils.format_time(doc.posting_time, "HH:mm") if doc.posting_time else "")) }}
{% if doc.is_return and doc.return_against %}{{ row(_("Return of", context=R), doc.return_against) }}
{% endif %}{{ row(_("Cashier", context=R), cashier) }}
{% if doc.customer_name %}{{ row(_("Customer", context=R), doc.customer_name) }}
{% endif %}{% if doc.sales_team %}{% set sp = namespace(names=[]) %}{% for st in doc.sales_team %}{% set sp.names = sp.names + [st.sales_person_name or st.sales_person] %}{% endfor %}{{ row(_("Sales Person", context=R), sp.names | select | join(", ")) }}
{% endif %}{% if doc.coupon_code %}{{ row(_("Coupon", context=R), doc.coupon_code) }}
{% endif %}{{ rule }}
{% for item in doc.items -%}
{%- set q = item.qty * sgn -%}
{%- set list_rate = item.price_list_rate or 0 -%}
{%- set discounted = list_rate > item.rate and not item.is_free_item -%}
{%- set unit = list_rate if discounted else item.rate -%}
{%- set gross = q * unit -%}
{%- set qty_text = qty(q) ~ ((" " ~ _(item.uom)) if (uom_after_qty and item.uom) else "") -%}
{{ item.item_name or item.item_code }}
{% if item.is_free_item %}{{ row(qty_text, _("Free", context=R)) }}{% else %}{{ row(qty_text ~ " x " ~ money(unit), money(gross)) }}{% endif %}
{% if discounted %}{{ row("  " ~ _("Discount", context=R), "-" ~ money(gross - item.amount * sgn)) }}
{% endif %}{% if item.serial_no %}  {{ _("Serial No", context=R) }} {{ item.serial_no | replace("\n", ", ") }}
{% endif %}{% if item.batch_no %}  {{ _("Batch", context=R) }} {{ item.batch_no }}
{% endif %}{% endfor %}{{ _("Items: {0}", context=R).format(doc.items | length) }}
{{ rule }}
{% set taxes = doc.taxes | selectattr("tax_amount") | list %}{% if doc.discount_amount or taxes or doc.rounding_adjustment %}{{ row(_("Subtotal", context=R), money(doc.total * sgn)) }}
{% endif %}{% if doc.discount_amount %}{{ row(_("Discount", context=R), "-" ~ money(doc.discount_amount | abs)) }}
{% endif %}{% for tax in taxes %}{{ row(tax.description, money(tax.tax_amount * sgn)) }}
{% endfor %}{% if doc.rounding_adjustment and not doc.disable_rounded_total %}{{ row(_("Rounding", context=R), money(doc.rounding_adjustment * sgn)) }}
{% endif %}{{ "\x1B!\x08" }}{{ row(_("Refund Total", context=R) if doc.is_return else _("Total", context=R), frappe.utils.fmt_money(total_due * sgn, currency=doc.currency)) }}{{ "\x1B!\x00" }}
{% set payments = doc.payments | selectattr("amount") | list %}{% if payments %}{{ rule }}
{% for payment in payments %}{{ row(_(payment.mode_of_payment), money(payment.amount * sgn)) }}
{% endfor %}{% if payments | length > 1 or doc.change_amount %}{{ row(_("Refunded", context=R) if doc.is_return else _("Paid", context=R), money((doc.paid_amount or 0) * sgn)) }}
{% endif %}{% if doc.change_amount and doc.change_amount > 0 %}{{ row(_("Change", context=R), money(doc.change_amount)) }}
{% endif %}{% endif %}{% if not doc.is_return and doc.outstanding_amount and doc.outstanding_amount > 0 %}{{ "\x1B!\x08" }}{{ row(_("Balance Due", context=R), money(doc.outstanding_amount)) }}{{ "\x1B!\x00" }}
{% endif %}{{ rule }}
{{ "\x1Ba\x01" }}{{ _("Thank you for your business!", context=R) }}


{{ "\x1DVA\x00" }}
